
.section {
  background: var(--c-surface-light);
  border-radius: 8px;
  padding: 10px 12px;
}

.section-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--c-warning);
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 6px;
}

.stat-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
  margin-bottom: 6px;
}

.stat-item {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 12px;
}

.label {
  color: var(--c-text-muted);
}

.value {
  color: var(--c-text);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.tag {
  padding: 1px 6px;
  border-radius: 4px;
  font-size: 11px;
}

.tag-active {
  background: var(--c-primary);
  color: #fff;
}

.tag-inactive {
  background: var(--c-surface);
  color: var(--c-text-muted);
}

.toggle-row {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-top: 6px;
}

.toggle-list {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}

.toggle-tag {
  padding: 1px 6px;
  border-radius: 4px;
  font-size: 11px;
  background: var(--c-danger);
  color: #fff;
}
