
.section {
  background: var(--c-surface-light);
  border-radius: 8px;
  padding: 10px 12px;
}

.section-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--c-accent);
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 6px;
}

.bar-item {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 6px;
}

.label {
  color: var(--c-text-muted);
  min-width: 70px;
  font-size: 12px;
}

.bar-container {
  flex: 1;
  height: 8px;
  background: var(--c-surface);
  border-radius: 4px;
  overflow: hidden;
}

.bar-fill {
  height: 100%;
  background: var(--c-accent);
  border-radius: 4px;
  transition: width 0.3s ease;
}

.value {
  color: var(--c-text);
  min-width: 30px;
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.tag-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 6px;
}

.tag-item {
  display: flex;
  align-items: center;
  gap: 4px;
}

.tag {
  padding: 1px 8px;
  border-radius: 4px;
  font-size: 12px;
  background: var(--c-surface);
  color: var(--c-text);
}

.tag-low { background: var(--c-success); color: #fff; }
.tag-mid { background: var(--c-warning); color: #2d3436; }
.tag-high { background: var(--c-danger); color: #fff; }
