
.section {
  background: var(--c-surface-light);
  border-radius: 8px;
  padding: 10px 12px;
}

.section-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--c-primary);
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 6px;
}

.info-grid {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.info-item {
  display: flex;
  gap: 8px;
  align-items: baseline;
}

.label {
  color: var(--c-text-muted);
  min-width: 40px;
  font-size: 12px;
}

.value {
  color: var(--c-text);
}
